function upperFirstEachWord(phrase: string): string {
  return (phrase?.charAt?.(0)?.toUpperCase?.() ?? '') + phrase?.slice?.(1);
}

function uniqueValuesFilter<T>(currentValue: T, currentIndex: number, sourceArray: T[]) {
  return sourceArray.indexOf(currentValue) === currentIndex;
}

export function displayProvider(
  firstName: string,
  lastName: string,
  suffix: string | undefined,
): string {
  const name = `${upperFirstEachWord(firstName)} ${upperFirstEachWord(lastName)}`;
  return suffix ? `${name}, ${suffix.toUpperCase()}` : name;
}

export function formatTaxonomies(
  taxonomies: {
    subSpecialtyDescription?: string | null;
    taxonomyDisplayName: string;
  }[],
): string {
  return taxonomies
    .map((tax) => tax.subSpecialtyDescription || tax.taxonomyDisplayName)
    .filter(uniqueValuesFilter)
    .join(', ')
    .trim();
}
