import React from 'react';
import classNames from 'classnames';

import ProviderLogo from '../../atoms/providerLogo';
import Text from '../../atoms/text';
import CancelX from '../../atoms/svgs/cancelX';

import { SizeEnum, AlignEnum, ColorNameEnum, WeightEnum } from '../../types/enums';

import { displayProvider, formatTaxonomies, phoneFormatter } from '../../lib';
import './index.less';
import './MiniCard.less';
import ClickableDiv from '../../atoms/clickableDiv';

import { ProviderInterface, NpiType } from '../../types';

export type ProviderCardProps = {
  provider: ProviderInterface;
  className?: string;
  showShadow?: boolean;
  showCancellationIcon?: boolean | undefined;
};

function ProviderCard({
  provider,
  className,
  showShadow,
  showCancellationIcon = false,
}: ProviderCardProps) {
  const { firstName, lastName, suffix, officeName, npiType = NpiType.INDIVIDUAL } = provider;

  const providerDisplayName = displayProvider(firstName, lastName, suffix);
  const isFacility = npiType === NpiType.ORGANIZATION;
  const title = isFacility ? officeName : providerDisplayName;
  return (
    <ClickableDiv
      className={classNames(className, 'card mini-doctor-card', {
        'no-shadow': !showShadow,
      })}
    >
      <div className="card-body">
        <div className="card-left">
          <div className="card-img">
            <ProviderLogo containerClass="small" provider={provider} />
            {showCancellationIcon && <CancelX className="cancellation-icon" />}
          </div>
        </div>
        <div className="doctor-info">
          <Text
            className="facility-name"
            weight={WeightEnum.bold}
            size={SizeEnum['16px']}
            align={AlignEnum.left}
            colorName={ColorNameEnum.ultraDark}
            ellipsis={false}
          >
            {title}
          </Text>
          {!isFacility && provider.taxonomies && (
            <Text
              colorName={ColorNameEnum.ultraDark}
              align={AlignEnum.left}
              size={SizeEnum['13px']}
            >
              {formatTaxonomies(provider.taxonomies)}
            </Text>
          )}
          {provider.clinicPhoneNumber && (
            <Text
              size={SizeEnum['12px']}
              align={AlignEnum.left}
              colorName={ColorNameEnum.ultraDark}
              className="margin-top-20"
            >
              {phoneFormatter.formatPhoneToLocal(provider.clinicPhoneNumber)}
            </Text>
          )}
          {!isFacility && (
            <Text
              size={SizeEnum['12px']}
              align={AlignEnum.left}
              colorName={ColorNameEnum.ultraDark}
              className="margin-top-5"
            >
              <strong>{provider.officeName}</strong>
            </Text>
          )}
          <Text
            size={SizeEnum['12px']}
            align={AlignEnum.left}
            colorName={ColorNameEnum.ultraDark}
            className="margin-top-5"
            text={provider.address}
          />
        </div>
      </div>
    </ClickableDiv>
  );
}

export default ProviderCard;
